#!/usr/bin/env python3
"""
Parse Wikidata-style coordinates and produce a clean POI table.
"""

import json
import csv
import re
import os

def parse_wikidata_coordinate(coord_str):
    """
    Parse Wikidata coordinate format.
    Common formats: "+48.8566+2.3522", "48.8566,2.3522", "+48.8566 +2.3522"
    Returns (latitude, longitude) as floats or None if parsing fails.
    """
    if not coord_str or not isinstance(coord_str, str):
        return None

    # Remove common prefixes/suffixes and normalize
    coord_str = coord_str.strip()

    # Try pattern: +lat+lon or +lat +lon
    match = re.match(r'^\s*(\+?)(-?\d+\.?\d*)\s*([+\s,]+)\s*(\+?)(-?\d+\.?\d*)\s*$', coord_str)
    if match:
        try:
            lat = float(match.group(2))
            lon = float(match.group(4))
            # Validate ranges
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return (lat, lon)
        except (ValueError, TypeError):
            pass

    # Try pattern: lat,lon or lat lon
    match = re.match(r'^\s*(-?\d+\.?\d*)\s*([,\s]+)\s*(-?\d+\.?\d*)\s*$', coord_str)
    if match:
        try:
            lat = float(match.group(1))
            lon = float(match.group(3))
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return (lat, lon)
        except (ValueError, TypeError):
            pass

    return None

def extract_poi_type(item):
    """
    Extract POI type from Wikidata item.
    Look for common properties like P31 (instance of) or similar.
    """
    # Check if there's a direct type field
    if 'poi_type' in item and item['poi_type']:
        return item['poi_type']

    # Check common Wikidata property patterns
    # P31 is typically "instance of"
    if 'claims' in item:
        claims = item['claims']
        if isinstance(claims, dict):
            # Look for P31 (instance of)
            if 'P31' in claims:
                p31_values = claims['P31']
                if isinstance(p31_values, list) and len(p31_values) > 0:
                    first_val = p31_values[0]
                    if isinstance(first_val, dict) and 'mainsnak' in first_val:
                        mainsnak = first_val['mainsnak']
                        if 'datavalue' in mainsnak and 'value' in mainsnak['datavalue']:
                            value = mainsnak['datavalue']['value']
                            # Could be a Wikidata entity like {"entity-type": "item", "id": "Q123"}
                            if isinstance(value, dict) and 'id' in value:
                                return value['id']
                    elif isinstance(first_val, str):
                        return first_val

    # Check for direct property access
    if 'properties' in item:
        props = item['properties']
        if isinstance(props, dict):
            # P31 is instance of
            if 'P31' in props:
                p31_vals = props['P31']
                if isinstance(p31_vals, list) and len(p31_vals) > 0:
                    val = p31_vals[0]
                    if isinstance(val, dict):
                        if 'mainsnak' in val:
                            sn = val['mainsnak']
                            if 'datavalue' in sn and 'value' in sn['datavalue']:
                                dv = sn['datavalue']['value']
                                if isinstance(dv, dict) and 'id' in dv:
                                    return dv['id']

    return None

def get_label(item, qid):
    """
    Get label from item, fallback to qid if not available.
    """
    # Check for itemLabel field (common in SPARQL results)
    if 'itemLabel' in item and item['itemLabel']:
        return str(item['itemLabel']).strip()

    # Check for label field
    if 'label' in item and item['label']:
        return str(item['label']).strip()

    # Check for labels object (multilingual)
    if 'labels' in item and isinstance(item['labels'], dict):
        labels = item['labels']
        # Try English first
        if 'en' in labels and isinstance(labels['en'], dict):
            if 'value' in labels['en']:
                val = labels['en']['value']
                if val:
                    return str(val).strip()
        # Try any available language
        for lang, lang_data in labels.items():
            if isinstance(lang_data, dict) and 'value' in lang_data:
                val = lang_data['value']
                if val:
                    return str(val).strip()

    # Fallback to qid
    return str(qid)

def process_wikidata_pois(input_path, output_path):
    """
    Main function to process Wikidata POIs and create clean CSV.
    """
    # Read input JSON
    with open(input_path, 'r', encoding='utf-8') as f:
        data = json.load(f)

    pois = []
    seen_qids = set()

    # Handle different JSON structures
    if isinstance(data, list):
        items = data
    elif isinstance(data, dict):
        # Check common structures
        if 'results' in data:
            items = data['results']
        elif 'items' in data:
            items = data['items']
        elif 'query' in data and 'results' in data['query']:
            items = data['query']['results']
        elif 'results' in data and isinstance(data['results'], dict):
            # SPARQL-like results with result bindings
            items = data['results']['bindings'] if 'bindings' in data['results'] else []
        else:
            items = [data]
    else:
        items = []

    for item in items:
        if not isinstance(item, dict):
            continue

        # Extract qid
        qid = None
        if 'qid' in item:
            qid = str(item['qid'])
        elif 'id' in item:
            qid = str(item['id'])
        elif 'item' in item:
            qid = str(item['item'])

        # Handle SPARQL-style result bindings
        if qid is None:
            if 'qid' in item and isinstance(item['qid'], dict):
                if 'value' in item['qid']:
                    qid = str(item['qid']['value'])
            elif 'id' in item and isinstance(item['id'], dict):
                if 'value' in item['id']:
                    qid = str(item['id']['value'])

        if not qid:
            continue

        # Skip duplicates
        if qid in seen_qids:
            continue
        seen_qids.add(qid)

        # Get label
        label = get_label(item, qid)

        # Get POI type
        poi_type = extract_poi_type(item)
        if not poi_type:
            poi_type = ""

        # Extract coordinates
        lat = None
        lon = None

        # Try various coordinate field names
        coord_field = None
        for field in ['coordinates', 'coords', 'location', 'geo']:
            if field in item:
                coord_field = item[field]
                break

        # Also check SPARQL-style bindings
        if coord_field is None:
            for field in ['coordinates', 'coords', 'location', 'geo']:
                if field in item and isinstance(item[field], dict):
                    if 'value' in item[field]:
                        coord_field = item[field]['value']
                        break

        if coord_field is not None:
            # Handle different coordinate formats
            if isinstance(coord_field, str):
                result = parse_wikidata_coordinate(coord_field)
                if result:
                    lat, lon = result
            elif isinstance(coord_field, dict):
                # Could be {"latitude": ..., "longitude": ...}
                if 'latitude' in coord_field and 'longitude' in coord_field:
                    try:
                        lat = float(coord_field['latitude'])
                        lon = float(coord_field['longitude'])
                        if not (-90 <= lat <= 90 and -180 <= lon <= 180):
                            lat = lon = None
                    except (ValueError, TypeError):
                        pass
                elif 'value' in coord_field:
                    # Nested value
                    result = parse_wikidata_coordinate(coord_field['value'])
                    if result:
                        lat, lon = result
            elif isinstance(coord_field, (list, tuple)) and len(coord_field) >= 2:
                try:
                    lat = float(coord_field[0])
                    lon = float(coord_field[1])
                    if not (-90 <= lat <= 90 and -180 <= lon <= 180):
                        lat = lon = None
                except (ValueError, TypeError):
                    pass

        # Skip if no valid coordinates
        if lat is None or lon is None:
            continue

        pois.append({
            'qid': qid,
            'label': label,
            'poi_type': poi_type,
            'latitude': lat,
            'longitude': lon,
            'source': 'wikidata'
        })

    # Ensure output directory exists
    os.makedirs(os.path.dirname(output_path), exist_ok=True)

    # Write CSV
    fieldnames = ['qid', 'label', 'poi_type', 'latitude', 'longitude', 'source']
    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        for poi in pois:
            writer.writerow(poi)

    return len(pois)

if __name__ == '__main__':
    input_path = 'inputs/wikidata/wikidata_pois_sample.json'
    output_path = 'outputs/t08_pois_clean.csv'

    count = process_wikidata_pois(input_path, output_path)
    print(f"Processed {count} POIs and wrote to {output_path}")
